
const tarefas = [];

let proximoCodigo = 0;

const formulario = document.getElementById("formTarefa");
const campoTitulo = document.getElementById("titulo");
const campoPrioridade = document.getElementById("prioridade");
const listaTarefas = document.getElementById("listaTarefas");
const mensagem = document.getElementById("mensagem");

// 1. Validação dos dados da tarefa
function validarDadosDaTarefa(titulo, prioridade) {
    if (titulo.trim().length < 5) {
            throw new Error(
                        "O título deve ter no mínimo 5 caracteres."
                                );
                                    }

                                        const valorPrioridade = Number(prioridade);

                                            if (
                                                    prioridade === "" ||
                                                            !Number.isInteger(valorPrioridade) ||
                                                                    valorPrioridade < 1 ||
                                                                            valorPrioridade > 3
                                                                                ) {
                                                                                        throw new Error(
                                                                                                    "A prioridade deve ser um número entre 1 e 3."
                                                                                                            );
                                                                                                                }
                                                                                                                }

                                                                                                                // 2. Cadastro de uma tarefa
                                                                                                                function cadastrarTarefa(titulo, prioridade) {
                                                                                                                    validarDadosDaTarefa(titulo, prioridade);

                                                                                                                        proximoCodigo++;

                                                                                                                            const tarefa = {
                                                                                                                                    codigo: proximoCodigo,
                                                                                                                                            titulo: titulo.trim(),
                                                                                                                                                    prioridade: Number(prioridade),
                                                                                                                                                            status: true
                                                                                                                                                                };

                                                                                                                                                                    tarefas.push(tarefa);

                                                                                                                                                                        return tarefa;
                                                                                                                                                                        }

                                                                                                                                                                        // 3. Listagem das tarefas cadastradas
                                                                                                                                                                        function listarTarefas() {
                                                                                                                                                                            return tarefas;
                                                                                                                                                                            }

                                                                                                                                                                            // 4. Busca de uma tarefa pelo código
                                                                                                                                                                            function buscarTarefa(codigo) {
                                                                                                                                                                                const tarefa = tarefas.find(
                                                                                                                                                                                        tarefa => tarefa.codigo === Number(codigo)
                                                                                                                                                                                            );

                                                                                                                                                                                                if (!tarefa) {
                                                                                                                                                                                                        throw new Error("Tarefa não encontrada.");
                                                                                                                                                                                                            }

                                                                                                                                                                                                                return tarefa;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                // 5. Conclusão de uma tarefa
                                                                                                                                                                                                                function concluirTarefa(codigo) {
                                                                                                                                                                                                                    const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                        if (!tarefa.status) {
                                                                                                                                                                                                                                throw new Error("Essa tarefa já foi concluída.");
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                        tarefa.status = false;

                                                                                                                                                                                                                                            return tarefa;
                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                            // 6. Alteração da prioridade
                                                                                                                                                                                                                                            function alterarPrioridade(codigo, novaPrioridade) {
                                                                                                                                                                                                                                                const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                    validarDadosDaTarefa(
                                                                                                                                                                                                                                                            tarefa.titulo,
                                                                                                                                                                                                                                                                    novaPrioridade
                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                            tarefa.prioridade = Number(novaPrioridade);

                                                                                                                                                                                                                                                                                return tarefa;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                // 7. Exibição de mensagens
                                                                                                                                                                                                                                                                                function mostrarMensagem(texto, tipo) {
                                                                                                                                                                                                                                                                                    mensagem.textContent = texto;
                                                                                                                                                                                                                                                                                        mensagem.className = tipo;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        // 8. Exibição das tarefas na tela
                                                                                                                                                                                                                                                                                        function exibirTarefas() {
                                                                                                                                                                                                                                                                                            listaTarefas.replaceChildren();

                                                                                                                                                                                                                                                                                                if (tarefas.length === 0) {
                                                                                                                                                                                                                                                                                                        const aviso = document.createElement("p");
                                                                                                                                                                                                                                                                                                                aviso.className = "vazio";
                                                                                                                                                                                                                                                                                                                        aviso.textContent = "Nenhuma tarefa cadastrada.";

                                                                                                                                                                                                                                                                                                                                listaTarefas.appendChild(aviso);
                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                listarTarefas().forEach(tarefa => {
                                                                                                                                                                                                                                                                                                                                                        const cartao = document.createElement("article");
                                                                                                                                                                                                                                                                                                                                                                cartao.className = "tarefa";

                                                                                                                                                                                                                                                                                                                                                                        if (!tarefa.status) {
                                                                                                                                                                                                                                                                                                                                                                                    cartao.classList.add("concluida");
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                    const titulo = document.createElement("h3");
                                                                                                                                                                                                                                                                                                                                                                                                            titulo.textContent = tarefa.titulo;

                                                                                                                                                                                                                                                                                                                                                                                                                    const codigo = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                            codigo.textContent = `Código: ${tarefa.codigo}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                    const prioridade = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                            prioridade.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                        `Prioridade: ${tarefa.prioridade} - ` +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ["Baixa", "Média", "Alta"][tarefa.prioridade - 1];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const status = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status.textContent = tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? "Status: Em andamento"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "Status: Concluída";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const acoes = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            acoes.className = "acoes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const botaoConcluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoConcluir.textContent = tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "Concluir tarefa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "Tarefa concluída";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoConcluir.className = tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "btn-concluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "btn-desabilitado";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoConcluir.disabled = !tarefa.status;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botaoConcluir.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                concluirTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Tarefa concluída com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        exibirTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(erro.message, "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const botaoPrioridade = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoPrioridade.textContent = "Alterar prioridade";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botaoPrioridade.className = "btn-prioridade";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoPrioridade.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const resposta = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Digite a nova prioridade: 1 (Baixa), " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "2 (Média) ou 3 (Alta)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (resposta === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alterarPrioridade(tarefa.codigo, resposta);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Prioridade alterada com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            exibirTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarMensagem(erro.message, "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    acoes.append(botaoConcluir, botaoPrioridade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartao.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        titulo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    codigo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                prioridade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listaTarefas.appendChild(cartao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 9. Evento de cadastro do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formulario.addEventListener("submit", function(evento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cadastrarTarefa(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        campoTitulo.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    campoPrioridade.value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Tarefa cadastrada com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formulario.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    exibirTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(erro.message, "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Exibe a lista inicial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    exibirTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    